window.EP = {"name": "ch2", "label": "एपिसोड 2", "en": "Rule One: Never Look Back at the Ghat", "duration": 1115.68, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 15.48, "text": "चैप्टर टू। रूल वन: नेवर लुक बैक एट द घाट"}, {"start": 16.03, "end": 18.18, "text": "डे टू। देवप्रयाग रोड"}], "captions": [{"start": 19.73, "end": 23.97, "text": "काली एस-यू-वी पूरे रास्ते, पहाड़ से नीचे देहरादून तक,", "who": "", "voice": "narrator", "diary": false}, {"start": 23.97, "end": 26.13, "text": "हमसे चार गाड़ियाँ पीछे रही।", "who": "", "voice": "narrator", "diary": false}, {"start": 26.58, "end": 27.1, "text": "न पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 27.1, "end": 27.61, "text": "न दूर।", "who": "", "voice": "narrator", "diary": false}, {"start": 27.61, "end": 31.13, "text": "बस वहीं, जैसे लेक्चर के बीच में कोई डाउट,", "who": "", "voice": "narrator", "diary": false}, {"start": 31.13, "end": 33.53, "text": "जो दिमाग़ से निकलता ही नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 33.98, "end": 39.66, "text": "शाओनी आगे की दोनों सीटों के बीच झुकी, घुटनों पर रोहन की नोटबुक खुली हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 39.66, "end": 41.16, "text": "और चेहरे पर वो लुक,", "who": "", "voice": "narrator", "diary": false}, {"start": 41.16, "end": 45.66, "text": "जो तब आता है जब कोई प्रॉब्लम आख़िरकार इंटरेस्टिंग हो जाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 46.11, "end": 46.58, "text": "ओके।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 46.78, "end": 47.42, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 47.62, "end": 48.52, "text": "फ़ैक्ट्स।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 48.72, "end": 52.93, "text": "उसने मेरी तरफ़ एक उँगली उठाई, क्योंकि मैं आगे वाली सीट पर था,", "who": "", "voice": "narrator", "diary": false}, {"start": 52.93, "end": 54.93, "text": "और इसलिए सबसे नज़दीकी ऑडियंस।", "who": "", "voice": "narrator", "diary": false}, {"start": 55.13, "end": 55.42, "text": "एक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 55.42, "end": 58.85, "text": "रोहन सहगल के पास तुम्हारा नोटबुक है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 58.85, "end": 59.13, "text": "दो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 59.13, "end": 60.56, "text": "हमारे पास उसका।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 60.56, "end": 60.95, "text": "तीन।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 60.95, "end": 64.09, "text": "उसके नोटबुक में कोऑर्डिनेट्स हैं,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 64.09, "end": 68.0, "text": "ग्लेशियर की फ़ोटो है, और एक शब्द है: कोर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 68.0, "end": 68.38, "text": "चार।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 68.58, "end": 69.82, "text": "उसने पीछे देखे बिना,", "who": "", "voice": "narrator", "diary": false}, {"start": 69.82, "end": 72.54, "text": "अँगूठे से पीछे वाले शीशे की तरफ़ इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 72.74, "end": 74.23, "text": "एक गाड़ी हमारा पीछा कर रही है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 74.68, "end": 75.37, "text": "पाँच।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 75.57, "end": 79.39, "text": "क्षितिज ने पीछे की सीट से कहा, डायरी से नज़र उठाए बिना।", "who": "", "voice": "narrator", "diary": false}, {"start": 79.59, "end": 83.17, "text": "गब्बर भैया ने चालीस मिनट से एक भी जोक नहीं मारा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 83.62, "end": 86.11, "text": "गब्बर की आँखें रियर-व्यू मिरर में गईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 86.11, "end": 88.01, "text": "और क्षितिज की आँखों से मिलीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 88.46, "end": 89.65, "text": "क्योंकि ये मज़ाक नहीं है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 89.85, "end": 90.49, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 90.94, "end": 91.54, "text": "पुलिस?", "who": "", "voice": "narrator", "diary": false}, {"start": 91.74, "end": 92.52, "text": "मैंने सुझाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 92.97, "end": 96.09, "text": "शाओनी ने बहुत ज़्यादा पेशेंस के साथ मेरी तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 96.29, "end": 97.81, "text": "और क्या बोलेंगे, पार्थ?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 97.81, "end": 101.03, "text": "सर, एक आदमी ने हमारे प्रोफ़ेसर का नोटबुक ले लिया,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 101.03, "end": 102.88, "text": "और हमारे पास उसका नोटबुक है?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 103.08, "end": 104.57, "text": "उसने नोटबुक खट से बंद की।", "who": "", "voice": "narrator", "diary": false}, {"start": 104.77, "end": 106.72, "text": "टेक्निकली… अभी चोर हम हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 107.17, "end": 110.7, "text": "मैं चाहता हूँ कि आपसे कहूँ, मेरे पास कोई काउंटर-आर्ग्युमेंट था।", "who": "", "voice": "narrator", "diary": false}, {"start": 110.7, "end": 111.2, "text": "उसकी जगह,", "who": "", "voice": "narrator", "diary": false}, {"start": 111.2, "end": 114.84, "text": "मैंने वही किया जो कोई भी टेक-सैवी प्रोफ़ेसर क्राइसिस में करता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 114.84, "end": 115.73, "text": "मैंने गूगल किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 116.18, "end": 117.17, "text": "एन-डी पैंसठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 117.17, "end": 122.36, "text": "रिज़ल्ट्स आए: एक मोटरसाइकिल का पार्ट, एक कोरियन स्किनकेयर सीरम,", "who": "", "voice": "narrator", "diary": false}, {"start": 122.36, "end": 126.22, "text": "और नागालैंड में सड़क रिपेयर का एक सरकारी टेंडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 126.67, "end": 128.32, "text": "नंदा देवी, उन्नीस सौ पैंसठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 128.32, "end": 131.93, "text": "रिज़ल्ट्स में वो सब आया, जो इस किताब के इंट्रोडक्शन में है।", "who": "", "voice": "narrator", "diary": false}, {"start": 131.93, "end": 134.37, "text": "अगर आपने वो स्किप किया है, तो वापस जाइए।", "who": "", "voice": "narrator", "diary": false}, {"start": 134.37, "end": 135.29, "text": "मैं वेट करूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 135.29, "end": 137.98, "text": "उन लोगों का वेट करने में मैं बहुत अच्छा हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 137.98, "end": 139.51, "text": "जिन्होंने रीडिंग नहीं की।", "who": "", "voice": "narrator", "diary": false}, {"start": 139.96, "end": 143.64, "text": "मैंने वो सब, पहाड़ी सड़क पर चलती गाड़ी में पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 143.64, "end": 146.01, "text": "ऋषिकेश पार करते-करते, मेरा पेट,", "who": "", "voice": "narrator", "diary": false}, {"start": 146.01, "end": 149.16, "text": "पेट नहीं रहा… एक छोटा, ठंडा पत्थर बन गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 149.61, "end": 150.31, "text": "प्लूटोनियम।", "who": "", "voice": "narrator", "diary": false}, {"start": 150.51, "end": 152.51, "text": "मैंने ज़ोर से कहा… विंडस्क्रीन से।", "who": "", "voice": "narrator", "diary": false}, {"start": 152.96, "end": 157.79, "text": "पूरे एक हेयरपिन बेंड तक, गाड़ी में किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 158.24, "end": 161.68, "text": "फिर क्षितिज, बहुत धीरे, पीछे से:", "who": "", "voice": "narrator", "diary": false}, {"start": 161.88, "end": 162.14, "text": "भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 162.14, "end": 163.99, "text": "ये ट्रिप के बजट में नहीं था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 164.44, "end": 165.62, "text": "टेक्निकली।", "who": "", "voice": "narrator", "diary": false}, {"start": 165.82, "end": 166.78, "text": "मैंने उससे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 166.98, "end": 169.43, "text": "प्लूटोनियम की हाफ़-लाइफ़ इतनी लंबी है,", "who": "", "voice": "narrator", "diary": false}, {"start": 169.43, "end": 172.13, "text": "कि ये ट्रिप का बजट कभी ख़त्म ही नहीं होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 172.13, "end": 173.23, "text": "ई-एम-आई पे चलेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 173.23, "end": 174.39, "text": "हमारे पोते भरेंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 174.84, "end": 176.61, "text": "मैं अपने ही जोक पर हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 176.61, "end": 177.86, "text": "और कोई नहीं हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 178.31, "end": 183.18, "text": "शाओनी फिर आगे झुकी, और इस बार उसने नोटबुक की तरफ़ नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 183.18, "end": 186.91, "text": "उसने मेरी तरफ़ देखा, एक ऐसे एक्सप्रेशन के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 186.91, "end": 191.94, "text": "जो मैंने उसे जानने के इतने सालों में, बस गिनती की बार देखा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 192.39, "end": 193.01, "text": "पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 193.21, "end": 195.66, "text": "उसने इतना धीरे कहा कि सिर्फ़ मैं सुन सकूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 195.86, "end": 196.56, "text": "डर लग रहा है?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 197.01, "end": 197.79, "text": "मुझे?", "who": "", "voice": "narrator", "diary": false}, {"start": 197.79, "end": 200.6, "text": "मैं प्रोफ़ेसर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 200.6, "end": 202.94, "text": "मैं डेडपूल हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.94, "end": 203.56, "text": "मैं…", "who": "", "voice": "narrator", "diary": false}, {"start": 204.01, "end": 206.61, "text": "जितना बड़ा जोक, उतना बड़ा डर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 206.81, "end": 210.0, "text": "उसने ये ऐसे कहा, जैसे कोई फ़ॉर्मूला पढ़ रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 210.2, "end": 211.76, "text": "मैं तुम्हें जानती हूँ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 211.96, "end": 213.06, "text": "वो पीछे टिक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 213.26, "end": 213.73, "text": "ठीक है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 213.73, "end": 214.93, "text": "मुझे भी लग रहा है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 214.93, "end": 216.21, "text": "अब दोनों को पता है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 216.21, "end": 216.82, "text": "आगे बढ़ो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 217.27, "end": 218.37, "text": "यही है शाओनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 218.37, "end": 220.82, "text": "वो कभी आपका हाथ नहीं पकड़ेगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 220.82, "end": 221.33, "text": "वो बस,", "who": "", "voice": "narrator", "diary": false}, {"start": 221.33, "end": 229.71, "text": "बहुत प्रिसाइज़ली बताएगी कि उसे पता है आपका हाथ काँप रहा है… और फिर आपको एक नंबर्ड लिस्ट पकड़ा देगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 231.21, "end": 239.36, "text": "जब तक हम गंगा की घाटी में देवप्रयाग की तरफ़ मुड़े, सूरज पहाड़ियों के पीछे जा चुका था, और सड़क वो बन चुकी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 239.36, "end": 243.73, "text": "जो पहाड़ी सड़कें रात में बन जाती हैं: हेडलाइट की एक पट्टी,", "who": "", "voice": "narrator", "diary": false}, {"start": 243.73, "end": 247.21, "text": "और दोनों तरफ़ कुछ नहीं, सिवाय नदी की आवाज़ के।", "who": "", "voice": "narrator", "diary": false}, {"start": 247.66, "end": 249.49, "text": "एस-यू-वी अभी भी पीछे थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 249.49, "end": 251.93, "text": "अब वो चार गाड़ियाँ पीछे नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 251.93, "end": 254.0, "text": "अब कोई और गाड़ी थी ही नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 254.45, "end": 258.44, "text": "गब्बर ने दोनों हाथों से स्टीयरिंग पकड़ा, मेरी तरफ़ देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 258.44, "end": 261.72, "text": "और गला साफ़ किया, जैसे कोई क्लास लेने वाला हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 262.17, "end": 263.03, "text": "प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 263.23, "end": 263.87, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 264.07, "end": 265.13, "text": "आप पढ़ाते हो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 265.13, "end": 266.43, "text": "आज मैं पढ़ाऊँगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 266.63, "end": 269.56, "text": "उसने स्टीयरिंग छोड़े बिना एक उँगली उठाई,", "who": "", "voice": "narrator", "diary": false}, {"start": 269.56, "end": 272.93, "text": "एक ऐसी स्किल, जो अहमदाबाद में नहीं सिखाई जाती।", "who": "", "voice": "narrator", "diary": false}, {"start": 273.13, "end": 274.68, "text": "पहाड़ के रात के नियम।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 274.68, "end": 276.23, "text": "ध्यान से सुनो, तीनों।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 276.68, "end": 276.96, "text": "एक।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 276.96, "end": 278.82, "text": "रात को सीटी मत बजाओ।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 278.82, "end": 281.23, "text": "जो सुनता है… वो आ जाता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 281.68, "end": 282.7, "text": "दूसरी उँगली।", "who": "", "voice": "narrator", "diary": false}, {"start": 282.9, "end": 283.25, "text": "दो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 283.25, "end": 288.59, "text": "नदी किनारे अगर कोई नाम से बुलाए, पीछे मत देखो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 288.59, "end": 289.86, "text": "जवाब मत दो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 290.31, "end": 290.92, "text": "तीसरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 291.12, "end": 291.45, "text": "तीन।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 291.45, "end": 295.58, "text": "श्मशान घाट के पास से गुज़रो, तो सर झुका के गुज़रो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 296.03, "end": 296.45, "text": "क्यों?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 296.65, "end": 299.05, "text": "क्षितिज ने पीछे से पूछा, पेन तैयार।", "who": "", "voice": "narrator", "diary": false}, {"start": 299.5, "end": 302.83, "text": "गब्बर ने उसे मिरर में एक लंबे मोमेंट तक देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 302.83, "end": 306.46, "text": "फिर उसने हमें पहाड़ों के भूतों के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 306.91, "end": 310.05, "text": "पोलाइट अंग्रेज़ी वाले भूत नहीं, उसने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 310.05, "end": 312.5, "text": "जो होटल के कॉरिडोर में रहते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 312.5, "end": 313.41, "text": "पहाड़ी वाले।", "who": "", "voice": "narrator", "diary": false}, {"start": 313.41, "end": 319.46, "text": "गढ़वाल और कुमाऊँ में लोग मानते हैं, कि जो अपने वक़्त से पहले मर जाते हैं, जवान,", "who": "", "voice": "narrator", "diary": false}, {"start": 319.46, "end": 320.76, "text": "अचानक, घर से दूर,", "who": "", "voice": "narrator", "diary": false}, {"start": 320.76, "end": 324.89, "text": "और जिनका ठीक से अंतिम संस्कार नहीं होता… वो जाते नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 324.89, "end": 326.11, "text": "वो रुक जाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 326.56, "end": 331.22, "text": "उनमें सबसे ज़्यादा डर, उसने कहा, मसान का है: श्मशान की आत्मा।", "who": "", "voice": "narrator", "diary": false}, {"start": 331.22, "end": 334.88, "text": "मसान एक संगम से अगले संगम तक नदी पर राज करता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 334.88, "end": 337.78, "text": "और वहाँ रहता है, जहाँ चिताएँ जलती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 337.78, "end": 344.19, "text": "वो जवानों को पकड़ता है, ज़्यादातर लड़कियों और बच्चों को, और जिन्हें वो पकड़ लेता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 344.19, "end": 348.69, "text": "वो ऐसे बीमार पड़ते हैं, जिसका कोई डॉक्टर इलाज नहीं कर सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 348.69, "end": 355.79, "text": "जब किसी दुल्हन की बारात ऐसी जगह से गुज़रती है, तो बुज़ुर्ग उसके सिर पर चावल और सिक्के घुमाकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 355.79, "end": 359.61, "text": "उसके पीछे फेंक देते हैं, ताकि जो भी पीछे आ रहा हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 359.61, "end": 362.51, "text": "वो चढ़ावा ले ले, और दुल्हन को छोड़ दे।", "who": "", "voice": "narrator", "diary": false}, {"start": 362.96, "end": 367.39, "text": "फिर है छल, जो ठीक-ठीक भूत नहीं, बल्कि एक धोखा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 367.39, "end": 375.45, "text": "वो झरनों, नदियों, चौराहों और सुनसान रास्तों के पास, दोपहर में और शाम ढले इंतज़ार करता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 375.45, "end": 379.98, "text": "और जब वो आपको पकड़ता है, तो आपको अचानक डर लगता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 379.98, "end": 384.6, "text": "बुख़ार आता है, एक ऐसी उलझन, जिसे आप समझा नहीं सकते।", "who": "", "voice": "narrator", "diary": false}, {"start": 384.6, "end": 386.77, "text": "छल लग गया, लोग कहते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 387.22, "end": 388.07, "text": "और जंगल में?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 388.27, "end": 389.37, "text": "शाओनी ने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 389.37, "end": 393.38, "text": "ज़िंदगी में भूतों के बारे में ये उसका पहला सवाल था।", "who": "", "voice": "narrator", "diary": false}, {"start": 393.38, "end": 394.72, "text": "मैंने नोटिस किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 394.72, "end": 395.66, "text": "गब्बर ने भी।", "who": "", "voice": "narrator", "diary": false}, {"start": 396.11, "end": 397.87, "text": "जंगल में… ख़बीस।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 398.07, "end": 399.01, "text": "उसने उसे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 399.21, "end": 399.62, "text": "बड़ा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 399.62, "end": 400.19, "text": "पुराना।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 400.19, "end": 403.44, "text": "जानवर की शक्ल भी ले सकता है, आदमी की भी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 403.44, "end": 406.13, "text": "और चरवाहे की आवाज़ में बुलाता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 406.13, "end": 410.86, "text": "मुसाफ़िर सोचता है, कोई दोस्त पास में है… और आवाज़ के पीछे,", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 410.86, "end": 412.65, "text": "रास्ते से उतर जाता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 413.1, "end": 414.31, "text": "और जो पीछे जाता है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 414.51, "end": 415.36, "text": "क्षितिज ने पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 415.81, "end": 417.35, "text": "गब्बर ने जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 417.35, "end": 419.08, "text": "उसे देने की ज़रूरत नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 419.53, "end": 420.57, "text": "मैं बिलीवर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 420.57, "end": 421.95, "text": "मैंने आपको बताया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 421.95, "end": 429.34, "text": "लेकिन मैं एक ऐसा आदमी भी हूँ, जिसने तीन रिसर्च पेपर्स लिखे हैं, और मेरे दिमाग़ में वो बिलीवर और वो रिसर्चर,", "who": "", "voice": "narrator", "diary": false}, {"start": 429.34, "end": 434.17, "text": "अब एक-दूसरे का हाथ बहुत कसकर पकड़े हुए थे… और छोड़ने से मना कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 435.67, "end": 437.96, "text": "रात के नौ बजकर चालीस मिनट पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 437.96, "end": 441.99, "text": "एस-यू-वी ने हाई बीम ऑन की… और फ़ासला ख़त्म कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 442.44, "end": 444.14, "text": "आगे सड़क पतली हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 444.14, "end": 445.67, "text": "बाईं तरफ़: चट्टान।", "who": "", "voice": "narrator", "diary": false}, {"start": 445.67, "end": 450.76, "text": "दाईं तरफ़: नीचे नदी तक एक लंबी गहराई, अँधेरे में चाँदी जैसी।", "who": "", "voice": "narrator", "diary": false}, {"start": 451.21, "end": 451.82, "text": "पकड़ के बैठो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 452.02, "end": 453.64, "text": "गब्बर ने हम सबसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 453.64, "end": 456.73, "text": "फिर उसने बसंती की हेडलाइट्स… बंद कर दीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 457.18, "end": 460.9, "text": "मैं चाहूँगा कि अगले नब्बे सेकंड आपको शांति से बताऊँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 460.9, "end": 461.91, "text": "नहीं बता सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 461.91, "end": 465.99, "text": "मैं कभी ऐसी गाड़ी में नहीं बैठा था, जिसकी लाइटें बंद हों,", "who": "", "voice": "narrator", "diary": false}, {"start": 465.99, "end": 470.08, "text": "रात में, हिमालय की सड़क पर, और मैं इसे रेकमेंड नहीं करता।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.08, "end": 474.09, "text": "और अगर गब्बर सिंह नेगी कभी आपके लिए ऐसा करने का ऑफ़र दे,", "who": "", "voice": "narrator", "diary": false}, {"start": 474.09, "end": 475.24, "text": "तो मना कर दीजिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 475.24, "end": 476.75, "text": "वो याद से चला रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 476.75, "end": 479.9, "text": "पहाड़ी के ऊपर आसमान की शेप देखकर चला रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 479.9, "end": 483.77, "text": "एक पॉइंट पर, मुझे पूरा यक़ीन है, वो सूँघकर चला रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 483.77, "end": 487.78, "text": "पीछे की सीट पर, शाओनी का एक हाथ ग्रैब हैंडल पर जकड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 487.78, "end": 490.58, "text": "दूसरा अपने भाई के घुटने पर, और क्षितिज,", "who": "", "voice": "narrator", "diary": false}, {"start": 490.58, "end": 493.23, "text": "मैं क़सम खाता हूँ… अभी भी लिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 493.68, "end": 498.13, "text": "फिर गब्बर ने एक बजरी वाले रास्ते पर ज़ोर से बाईं तरफ़ मोड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 498.13, "end": 499.99, "text": "जो मैंने देखा तक नहीं था,", "who": "", "voice": "narrator", "diary": false}, {"start": 499.99, "end": 504.14, "text": "अँधेरे में से नदी गरजती हुई हमारी तरफ़ आई… और हम रुक गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 505.64, "end": 506.53, "text": "देवप्रयाग।", "who": "", "voice": "narrator", "diary": false}, {"start": 506.53, "end": 512.77, "text": "हमारे नीचे, कुछ कमज़ोर लैंप्स के नीचे, दो नदियाँ मिल रही थीं: भागीरथी,", "who": "", "voice": "narrator", "diary": false}, {"start": 512.77, "end": 517.85, "text": "तेज़ और हरी-सलेटी, और अलकनंदा, चौड़ी और ज़्यादा शोर वाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 517.85, "end": 521.15, "text": "यहाँ से, साथ मिलकर, वो गंगा बनती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 521.6, "end": 523.2, "text": "और पानी के बग़ल में,", "who": "", "voice": "narrator", "diary": false}, {"start": 523.2, "end": 527.84, "text": "घाट की पत्थर की सीढ़ियों पर… एक चिता की आख़िरी नारंगी चमक।", "who": "", "voice": "narrator", "diary": false}, {"start": 528.29, "end": 529.07, "text": "यहाँ क्यों?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 529.27, "end": 531.75, "text": "शाओनी ने गब्बर से फुसफुसाकर पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 532.2, "end": 535.0, "text": "क्योंकि यहाँ रात को कोई पीछा नहीं करता, दीदी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 535.2, "end": 536.8, "text": "उसने फुसफुसाकर जवाब दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 537.0, "end": 539.26, "text": "घाट पे नहीं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 539.71, "end": 541.96, "text": "ऊपर सड़क पर, एस-यू-वी रुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 541.96, "end": 543.29, "text": "एक दरवाज़ा खुला।", "who": "", "voice": "narrator", "diary": false}, {"start": 543.29, "end": 545.87, "text": "भारी क़दम, बजरी पर चरमराते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 545.87, "end": 551.04, "text": "एक टॉर्च की रोशनी रास्ते पर नीचे घूमी… और बसंती पर आकर रुक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 551.74, "end": 552.3, "text": "भल्ला।", "who": "", "voice": "narrator", "diary": false}, {"start": 553.0, "end": 557.46, "text": "वो ढलान पर धीरे-धीरे नीचे आया, एक बड़ा हाथ टॉर्च पर रखे।", "who": "", "voice": "narrator", "diary": false}, {"start": 557.46, "end": 558.09, "text": "दस मीटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 558.09, "end": 558.33, "text": "आठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 558.33, "end": 559.53, "text": "पीछे की सीट पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 559.53, "end": 563.51, "text": "शाओनी ने अपने दरवाज़े के हैंडल की तरफ़ हाथ बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 563.51, "end": 567.96, "text": "मैं क़सम खाता हूँ, वो बाहर निकलकर उससे बहस करने वाली थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 567.96, "end": 572.66, "text": "गब्बर ने बिना सिर घुमाए, सीटों के बीच से उसकी कलाई पकड़ ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 573.11, "end": 575.8, "text": "फिर उसने अपनी खिड़की का शीशा नीचे किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 575.8, "end": 577.74, "text": "और अँधेरे में, धीरे से बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 578.19, "end": 579.21, "text": "भाई साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 579.21, "end": 581.61, "text": "ये मसान का इलाक़ा है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 581.61, "end": 583.56, "text": "दो संगमों के बीच।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 583.76, "end": 585.35, "text": "उसने उसे थोड़ा बैठने दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 585.55, "end": 588.91, "text": "रात को यहाँ पीछे से कोई बुलाए… तो मुड़ के मत देखना।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 589.61, "end": 590.81, "text": "भल्ला रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 591.51, "end": 595.64, "text": "वो एक बहुत छोटा सा रुकना था, शायद आधे सेकंड की झिझक।", "who": "", "voice": "narrator", "diary": false}, {"start": 595.64, "end": 597.38, "text": "लेकिन क्षितिज ने देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 597.38, "end": 603.5, "text": "और क्षितिज, जिसने एक दिन पहले सुबह अपनी डायरी में लिखा था, कि वो काँप गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 603.5, "end": 609.7, "text": "जैसे उसने कोई असली भूत देखा हो… उसने इस पूरी ट्रिप पर किसी के भी द्वारा की गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 609.7, "end": 611.53, "text": "सबसे ब्रिलियंट चीज़ की।", "who": "", "voice": "narrator", "diary": false}, {"start": 611.98, "end": 614.96, "text": "उसने अपना फ़ोन पीछे की खिड़की से बाहर निकाला,", "who": "", "voice": "narrator", "diary": false}, {"start": 614.96, "end": 618.66, "text": "वॉल्यूम पूरा बढ़ाया, और गोलू की सवॉय वाली वीडियो चला दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 619.11, "end": 623.72, "text": "अँधेरे घाट के उस पार, दो नदियों की आवाज़ के ऊपर,", "who": "", "voice": "narrator", "diary": false}, {"start": 623.72, "end": 630.44, "text": "गोलू की फुसफुसाहट आई: घोस्ट फ़ैमिली… वो देखो… सफ़ेद साया… और उसके बाद,", "who": "", "voice": "narrator", "diary": false}, {"start": 630.44, "end": 631.21, "text": "वो चीख़।", "who": "", "voice": "narrator", "diary": false}, {"start": 631.21, "end": 632.17, "text": "असली वाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 632.17, "end": 633.51, "text": "सूप वाली चीख़।", "who": "", "voice": "narrator", "diary": false}, {"start": 634.21, "end": 634.93, "text": "भल्ला मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 635.63, "end": 637.63, "text": "वो मुड़ना नहीं चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 637.63, "end": 640.62, "text": "आप देख सकते थे, कि वो नहीं चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 640.62, "end": 642.45, "text": "उसका शरीर बस मुड़ गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 642.45, "end": 646.28, "text": "जैसे गरम तवे से आपका हाथ झटके से पीछे हटता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 646.28, "end": 651.18, "text": "वो अपने पीछे देखने के लिए मुड़ा, चिता की तरफ़, नदी की तरफ़,", "who": "", "voice": "narrator", "diary": false}, {"start": 651.18, "end": 656.26, "text": "अँधेरे की तरफ़: ठीक वही, जो गब्बर ने उसे करने से मना किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 656.71, "end": 660.49, "text": "और चिता की रोशनी में, मैंने उसके होंठ हिलते देखे।", "who": "", "voice": "narrator", "diary": false}, {"start": 660.49, "end": 661.57, "text": "कोई गाली नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 661.57, "end": 664.12, "text": "कुछ छोटा सा, बार-बार दोहराया हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 664.12, "end": 666.59, "text": "जैसे कोई प्रार्थना बुदबुदाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 666.59, "end": 667.67, "text": "या… कोई माफ़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 668.12, "end": 676.18, "text": "गब्बर ने लाइट्स ऑन कीं, बसंती को रिवर्स में डाला, उस बजरी पर उसे घुमाया, जिस पर मैं साइकिल भी पार्क न करूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 676.18, "end": 679.94, "text": "और एस-यू-वी के पास से गरजते हुए वापस ऊपर निकल गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 679.94, "end": 682.5, "text": "इससे पहले कि भल्ला वापस मुड़ पाता।", "who": "", "voice": "narrator", "diary": false}, {"start": 682.95, "end": 686.64, "text": "संगम के पास से गुज़रते हुए, मैंने सिर झुकाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 686.64, "end": 688.11, "text": "कुछ नदियों के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 688.11, "end": 690.65, "text": "कुछ उसके लिए, जो उस चिता पर था।", "who": "", "voice": "narrator", "diary": false}, {"start": 690.65, "end": 693.03, "text": "और कुछ, मैं मानता हूँ, इसलिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 693.03, "end": 696.63, "text": "कि मैं चाहता था कि ऊपर कोई हमारी साइड पर हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 697.08, "end": 701.09, "text": "पीछे, घाट की सीढ़ियों पर एक लंबा आकार खड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 701.09, "end": 704.75, "text": "हाथ से लटकती टॉर्च लिए, पानी को घूरता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.2, "end": 707.44, "text": "दो किलोमीटर बाद, गब्बर फिर बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 707.44, "end": 711.84, "text": "उसने मुझसे कहा, लेकिन इतनी ज़ोर से, कि पीछे की सीट तक सुनाई दे।", "who": "", "voice": "narrator", "diary": false}, {"start": 712.29, "end": 713.27, "text": "प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 713.27, "end": 717.29, "text": "आप लोगों ने कभी सोचा है… इतना बड़ा आदमी, भूत से क्यों डरता है?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 717.74, "end": 721.66, "text": "जवाब क्षितिज ने दिया, धीरे से, पहले से लिखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 722.11, "end": 723.63, "text": "क्योंकि उसने कुछ देखा है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 725.13, "end": 730.82, "text": "श्रीनगर के आगे, आधी रात से थोड़ा पहले, हम एक ढाबे पर रुके: कड़क चाय,", "who": "", "voice": "narrator", "diary": false}, {"start": 730.82, "end": 735.85, "text": "सुबह से चूल्हे पर चढ़ा राजमा, और एक तेल के ड्रम में जलती आग।", "who": "", "voice": "narrator", "diary": false}, {"start": 735.85, "end": 737.69, "text": "मसूरी के बाद पहली बार,", "who": "", "voice": "narrator", "diary": false}, {"start": 737.69, "end": 742.47, "text": "मेरे हाथों ने इतना काँपना बंद किया कि एक गिलास पकड़ सकूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 742.92, "end": 745.94, "text": "गब्बर ने टेबल के उस पार से मेरी तरफ़ हाथ बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 746.14, "end": 746.78, "text": "नोटबुक।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 747.23, "end": 748.21, "text": "मैंने दे दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 748.21, "end": 750.1, "text": "उसने गीत वाला पेज खोला,", "who": "", "voice": "narrator", "diary": false}, {"start": 750.1, "end": 754.6, "text": "और अपनी मोटी उँगली लाइनों के नीचे चलाई, होंठ हिलते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 754.6, "end": 759.59, "text": "फिर उसने कुछ ऐसा किया, जिसकी हममें से किसी को उम्मीद नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 760.29, "end": 761.39, "text": "उसने उसे गाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 762.09, "end": 771.14, "text": "धीरे से, आग की चटचटाहट से बस थोड़ा ऊपर, एक ऐसी आवाज़ में, जो उस आदमी जैसी बिल्कुल नहीं थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 771.14, "end": 776.97, "text": "जिसने अभी-अभी अँधेरे में पहाड़ से नीचे अंधी गाड़ी चलाई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 777.42, "end": 781.67, "text": "जहाँ पानी के बदले बेटा दिया, वहाँ से पहला पाठ लिया…", "who": "", "voice": "narrator", "diary": false}, {"start": 782.12, "end": 786.42, "text": "चार लाइनों के बाद वो रुक गया, और कुछ देर आग में देखता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 786.87, "end": 788.62, "text": "मेरी नानी गाती थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 788.82, "end": 789.92, "text": "उसने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 790.12, "end": 792.13, "text": "कुमाऊँ के ऊपर वाले गाँव में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 792.13, "end": 793.14, "text": "बचपन में सुना।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 793.14, "end": 795.08, "text": "हम सोचते थे, बस एक गाना है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 795.08, "end": 796.66, "text": "एक गरम पत्थर की कहानी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 796.86, "end": 800.36, "text": "उसने माथे पर बल डाले, जैसे कुछ याद करने की कोशिश कर रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 800.56, "end": 807.3, "text": "कहती थी, जिस साल पहाड़ पे हेलिकॉप्टर आए थे… अगले बसंत में चरवाहों ने बर्फ़ में एक पत्थर देखा,", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 807.3, "end": 808.75, "text": "जिससे भाप उठ रही थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 809.2, "end": 810.51, "text": "शाओनी आगे झुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 810.71, "end": 811.31, "text": "उसके बाद?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 811.76, "end": 812.96, "text": "गब्बर ने सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 813.16, "end": 815.59, "text": "नानी ने कभी आगे नहीं सुनाया, दीदी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 815.59, "end": 818.88, "text": "बस इतना कहती थी: जिसने छुआ, वो लौट के ना रोया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 819.33, "end": 819.9, "text": "मतलब?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 820.1, "end": 821.28, "text": "क्षितिज ने उससे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 821.73, "end": 826.68, "text": "मतलब जिसने उसे छुआ, उसने फिर कभी किसी बात पे नहीं रोया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 826.88, "end": 827.6, "text": "गब्बर रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 827.8, "end": 829.72, "text": "या फिर… वो लौट के ही नहीं आया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 830.17, "end": 830.83, "text": "आग चटकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 830.83, "end": 835.39, "text": "कहीं अँधेरे में, एक कुत्ता दो बार भौंका, और चुप हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 835.84, "end": 837.36, "text": "चुप्पी क्षितिज ने तोड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 837.56, "end": 838.96, "text": "आपकी नानी अब…?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 839.41, "end": 840.69, "text": "बहुत साल पहले।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 840.89, "end": 844.97, "text": "गब्बर अपना चाय का गिलास हथेलियों के बीच घुमाता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 845.17, "end": 846.38, "text": "ईजा है अभी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 846.38, "end": 847.36, "text": "मेरी माँ।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 847.36, "end": 848.35, "text": "गाँव में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 848.35, "end": 849.01, "text": "अकेली।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 849.21, "end": 850.81, "text": "वो एक पल चुप रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 851.01, "end": 853.05, "text": "दो साल हो गए, मिलने नहीं गया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 853.05, "end": 855.51, "text": "हर साल सोचता हूँ, इस दिवाली जाऊँगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 855.51, "end": 857.13, "text": "हर साल सीज़न आ जाता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 857.13, "end": 858.47, "text": "टूरिस्ट आ जाते हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 858.47, "end": 860.37, "text": "बसंती की ई-एम-आई आ जाती है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 860.82, "end": 863.47, "text": "उसने कंधे उचकाए, एक बड़े आदमी का कंधे उचकाना,", "who": "", "voice": "narrator", "diary": false}, {"start": 863.47, "end": 864.89, "text": "जो ठीक से काम नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 865.34, "end": 868.26, "text": "ईजा फ़ोन पे कहती है, कोई बात नहीं, तू काम कर।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 868.26, "end": 870.07, "text": "पहाड़ी माएँ ऐसी ही होती हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 870.07, "end": 871.5, "text": "कभी शिकायत नहीं करतीं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 871.5, "end": 872.99, "text": "इसलिए… और बुरा लगता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 873.19, "end": 874.67, "text": "उसने आग में देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 874.87, "end": 876.5, "text": "इस बार तो बुलाया भी था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 876.5, "end": 879.32, "text": "गाँव में जागर होने वाला है, अगले हफ़्ते।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 879.32, "end": 880.45, "text": "एक लड़के के लिए।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 880.45, "end": 883.28, "text": "बुज़ुर्ग कहते हैं, उसे मसान ने पकड़ा है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 883.28, "end": 885.47, "text": "ईजा बोली, आ जाता तो अच्छा लगता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 885.92, "end": 886.86, "text": "और आपने क्या कहा?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 887.06, "end": 889.14, "text": "शाओनी ने बहुत नरमी से पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 889.59, "end": 891.88, "text": "मैंने कहा… सीज़न है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 892.33, "end": 895.46, "text": "उसने नोटबुक बहुत सावधानी से टेबल पर रखी,", "who": "", "voice": "narrator", "diary": false}, {"start": 895.46, "end": 897.33, "text": "जैसे वो उसकी नानी की हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 897.78, "end": 900.82, "text": "वो ये गीत गाती थी, और मैं सुनता नहीं था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 901.02, "end": 901.66, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 901.86, "end": 904.08, "text": "मुझे सिर्फ़ गाड़ियों का शौक़ था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 904.08, "end": 906.17, "text": "सोचा था… गाने तो हमेशा रहेंगे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 906.62, "end": 909.76, "text": "उस बात के लिए किसी के पास कोई जोक नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 909.76, "end": 911.04, "text": "मेरे पास भी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 912.54, "end": 918.84, "text": "तभी एक सफ़ेद एस-यू-वी, डैशबोर्ड पर रिंग लाइट लगाए, ढाबे में आकर रुकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 918.84, "end": 922.58, "text": "और लाल पफ़र जैकेट में एक आदमी बाहर निकला,", "who": "", "voice": "narrator", "diary": false}, {"start": 922.58, "end": 924.77, "text": "पहले से फ़िल्म करता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 925.22, "end": 926.44, "text": "घोस्ट फ़ैमिली!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 926.64, "end": 930.4, "text": "गोलू ने हमें देखा, और कैमरा सीधा हमारी टेबल की तरफ़ कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 930.6, "end": 931.97, "text": "क्या कोइन्सिडेंस है!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 931.97, "end": 933.21, "text": "वही सवॉय वाली टीम!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 933.21, "end": 936.16, "text": "मैं केदारनाथ जा रहा हूँ, भूत कंटेंट के लिए।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 936.16, "end": 936.84, "text": "आप लोग भी?", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 937.29, "end": 939.61, "text": "शाओनी की आँखें सिकुड़ गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 939.61, "end": 941.83, "text": "उसने उसकी तरफ़ नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 941.83, "end": 943.61, "text": "उसने मेरी तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 943.81, "end": 944.8, "text": "कोइन्सिडेंस?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 945.25, "end": 945.96, "text": "बिल्कुल, दीदी!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 946.16, "end": 949.84, "text": "गोलू ने चहककर जवाब दिया, हालाँकि उसने उससे पूछा नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 950.04, "end": 951.52, "text": "पहाड़ में एक ही रोड है।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 952.22, "end": 954.5, "text": "जो, सच कहूँ तो, सही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 955.2, "end": 960.88, "text": "वो दो टेबल दूर बैठ गया, ठंड से बचने के लिए वो फीकी नीली टोपी कानों तक खींची,", "who": "", "voice": "narrator", "diary": false}, {"start": 960.88, "end": 963.12, "text": "मैगी ऑर्डर की, और लाइव हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 963.12, "end": 967.23, "text": "मैं उसके फ़ोन पर कमेंट्स की पिंग सुन सकता था: पचास, सौ।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.23, "end": 968.72, "text": "वो उन्हें अपनी लाउड,", "who": "", "voice": "narrator", "diary": false}, {"start": 968.72, "end": 972.16, "text": "ख़ुश यूट्यूब वाली आवाज़ में पढ़कर सुना रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 972.61, "end": 976.37, "text": "फिर उसका फ़ोन एक बार और बजा… और गोलू ने पढ़ना बंद कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 976.82, "end": 978.38, "text": "बस एक सेकंड के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 978.38, "end": 982.68, "text": "फिर वो हँसा, कुछ ज़्यादा ज़ोर से, और टॉपिक बदल दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 983.13, "end": 985.53, "text": "क्षितिज उसके सबसे पास बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 985.53, "end": 993.0, "text": "वो ऐसे उठा, जैसे और चाय लाने जा रहा हो, रास्ते में बड़े कैज़ुअली गोलू के कंधे के ऊपर से झुका,", "who": "", "voice": "narrator", "diary": false}, {"start": 993.0, "end": 997.01, "text": "और बहुत स्थिर चेहरे के साथ हमारी टेबल पर वापस आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 997.01, "end": 1002.79, "text": "उसने अपनी डायरी मेरे सामने रखी, खुली हुई, और उस लाइन की तरफ़ इशारा किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1002.79, "end": 1006.89, "text": "जो उसने अभी-अभी गोलू के लाइव स्ट्रीम के कमेंट्स से,", "who": "", "voice": "narrator", "diary": false}, {"start": 1006.89, "end": 1008.33, "text": "शब्दशः कॉपी की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1008.78, "end": 1012.41, "text": "एट एन-डी पैंसठ: नोटबुक वापस करो, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1012.41, "end": 1013.17, "text": "पोलाइटली।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1013.17, "end": 1014.1, "text": "अभी के लिए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1014.55, "end": 1016.1, "text": "मैंने गोलू की तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1016.1, "end": 1017.57, "text": "गोलू आग में देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1018.02, "end": 1021.77, "text": "उसने, मुझे एहसास हुआ, हमसे एक भी सवाल नहीं पूछा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1021.77, "end": 1026.9, "text": "कि अभी-अभी एक गाड़ी ने अँधेरे में पहाड़ से नीचे हमारा पीछा क्यों किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1027.6, "end": 1029.27, "text": "जैसे उसे… पहले से पता हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 1029.97, "end": 1031.8, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1031.8, "end": 1033.72, "text": "डे टू, देवप्रयाग रोड।", "who": "", "voice": "narrator", "diary": true}, {"start": 1034.17, "end": 1036.1, "text": "भल्ला भूतों से डरता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1036.1, "end": 1037.03, "text": "थोड़ा नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1037.03, "end": 1037.45, "text": "पूरा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1037.45, "end": 1042.16, "text": "जब गब्बर भैया ने उसे मना किया, तब भी वो घाट पर मुड़ गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1042.16, "end": 1045.01, "text": "ऐसा आदमी इतना यक़ीन क्यों करता है?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1045.46, "end": 1049.29, "text": "घाट पर, मुड़ने के बाद, भल्ला के होंठ हिले।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1049.29, "end": 1050.2, "text": "गाली नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1050.2, "end": 1051.93, "text": "छोटे शब्द, बार-बार।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1051.93, "end": 1052.84, "text": "प्रार्थना?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1052.84, "end": 1053.3, "text": "सॉरी?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1053.75, "end": 1056.65, "text": "गब्बर भैया की नानी वही गीत गाती थीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1056.65, "end": 1058.98, "text": "उनका गाँव ऊपरी कुमाऊँ में है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1058.98, "end": 1063.0, "text": "गीत कहता है, चरवाहों ने एक पत्थर से भाप उठती देखी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1063.0, "end": 1065.74, "text": "हेलिकॉप्टरों के बाद वाले बसंत में।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1065.74, "end": 1071.21, "text": "इंट्रोडक्शन कहता है, सी-आई-ए की टीम मई उन्नीस सौ छियासठ में वापस गई,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1071.21, "end": 1072.9, "text": "और उसे कुछ नहीं मिला।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1072.9, "end": 1075.23, "text": "क्या चरवाहे पहले पहुँच गए थे?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1075.68, "end": 1078.81, "text": "एट एन-डी पैंसठ वाला कमेंट गोलू के लाइव स्ट्रीम पर आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1078.81, "end": 1081.01, "text": "आर. को कैसे पता चला कि हम देख रहे हैं?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1081.01, "end": 1083.1, "text": "या आर. को पता था, कि गोलू यहाँ होगा?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1083.55, "end": 1086.28, "text": "गोलू ने कहा, पहाड़ में एक ही रोड है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1086.28, "end": 1088.85, "text": "पहाड़ों में एक से ज़्यादा रोड हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1088.85, "end": 1089.99, "text": "मैंने चेक किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1089.99, "end": 1092.19, "text": "केदारनाथ के लिए एक ही रोड है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1092.19, "end": 1093.17, "text": "लेकिन फिर भी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1093.62, "end": 1096.78, "text": "गब्बर भैया अपनी ईजा से दो साल से नहीं मिले।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1096.78, "end": 1099.86, "text": "उन्होंने ये ऐसे कहा, जैसे कोई कन्फ़ेशन हो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1099.86, "end": 1103.38, "text": "दीदी ने उनसे ईजा का नंबर माँगा, इमरजेंसी के लिए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1103.38, "end": 1106.68, "text": "मुझे लगता है, दीदी उनसे फ़ोन करवाने वाली हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 18.53, "bed": "roadday"}, {"at": 230.01, "bed": "roadnight"}, {"at": 260.97, "bed": "lore"}, {"at": 434.47, "bed": "chase"}, {"at": 504.44, "bed": "ghat"}, {"at": 723.93, "bed": "dhaba"}, {"at": 911.34, "bed": "golu"}, {"at": 1028.77, "bed": "diary"}, {"at": 1028.77, "bed": "diary"}], "hits": [{"at": 19.58, "fx": "suv"}, {"at": 149.46, "fx": "sting"}, {"at": 435.52, "fx": "sting"}, {"at": 493.53, "fx": "skid"}, {"at": 539.56, "fx": "cardoor"}, {"at": 551.59, "fx": "sting"}, {"at": 552.85, "fx": "steps_slow"}, {"at": 618.96, "fx": "phonevideo"}, {"at": 667.97, "fx": "carstart"}, {"at": 682.8, "fx": "bell"}, {"at": 721.96, "fx": "sting"}, {"at": 747.08, "fx": "page"}, {"at": 777.27, "fx": "flute"}, {"at": 830.02, "fx": "firepop"}, {"at": 912.39, "fx": "cardoor"}, {"at": 925.07, "fx": "golu"}, {"at": 972.46, "fx": "ping"}, {"at": 1008.63, "fx": "sting"}], "next": {"label": "एपिसोड 3", "en": "The Water That Cost a Son", "hook": "एक गाँव, जिसने पानी के बदले एक बेटा दिया। और एक गीत, जो सच निकला।"}};
